### ✅ Example 5 — `property()` Built-in Function & Advanced Patterns

```python name=example5_advanced_property.py
# ══════════════════════════════════════════════════════════
#  ADVANCED PROPERTY PATTERNS
#  1. property() function (older syntax)
#  2. Property inheritance and overriding
#  3. Class-level property (using descriptor)
#  4. Chaining properties for clean API
# ══════════════════════════════════════════════════════════

# ─── Pattern 1: property() built-in function (equivalent to decorator) ───
class Temperature:
    """
    Shows BOTH ways to create properties:
    - Decorator syntax (@property) ← preferred
    - property() function syntax   ← older, but useful to know
    """

    UNITS = ("C", "F", "K")

    def __init__(self, celsius=0.0):
        self._celsius = float(celsius)

    # ── Decorator syntax (Pythonic, preferred) ──
    @property
    def celsius(self):
        return self._celsius

    @celsius.setter
    def celsius(self, value):
        if value < -273.15:
            raise ValueError(f"❌ Below absolute zero! Got {value}°C")
        self._celsius = float(value)

    # ── property() function syntax (older) ──
    def _get_fahrenheit(self):
        return self._celsius * 9/5 + 32

    def _set_fahrenheit(self, value):
        self.celsius = (value - 32) * 5/9   # converts and uses celsius setter!

    fahrenheit = property(
        fget = _get_fahrenheit,
        fset = _set_fahrenheit,
        doc  = "Temperature in Fahrenheit"
    )

    # ── Read-only: Kelvin ──
    @property
    def kelvin(self):
        return self._celsius + 273.15

    # ── Read-only: State description ──
    @property
    def state(self):
        if self._celsius < 0:
            return "🧊 Frozen"
        elif self._celsius < 20:
            return "🌡️  Cold"
        elif self._celsius < 37:
            return "😊 Comfortable"
        elif self._celsius < 100:
            return "🔥 Hot"
        else:
            return "♨️  Boiling"

    def __str__(self):
        return (f"{self._celsius:.2f}°C = "
                f"{self.fahrenheit:.2f}°F = "
                f"{self.kelvin:.2f}K | {self.state}")

# ─── Pattern 2: Property inheritance — child overrides parent property ───
class BaseProduct:
    def __init__(self, name, base_price):
        self.name       = name
        self._base_price = base_price

    @property
    def price(self):
        return self._base_price

    @price.setter
    def price(self, value):
        if value < 0:
            raise ValueError("❌ Price cannot be negative")
        self._base_price = value

    @property
    def display_price(self):
        return f"₹{self.price:,.2f}"

class DiscountedProduct(BaseProduct):
    def __init__(self, name, base_price, discount_pct):
        super().__init__(name, base_price)
        self.discount_pct = discount_pct

    # ── OVERRIDE parent's price property ──
    @property
    def price(self):
        """Returns discounted price instead of base price"""
        return self._base_price * (1 - self.discount_pct / 100)

    @price.setter
    def price(self, value):
        """Must re-declare setter when overriding property!"""
        # Calls parent setter logic
        BaseProduct.price.fset(self, value)

    @property
    def original_price(self):
        return self._base_price

    @property
    def you_save(self):
        return self._base_price - self.price

    def __str__(self):
        return (f"{self.name}: "
                f"~~₹{self.original_price:,.0f}~~ "
                f"→ ₹{self.price:,.0f} "
                f"(Save ₹{self.you_save:,.0f}, {self.discount_pct}% off)")

# ─── Pattern 3: Chaining Properties for Fluent API ───
class QueryBuilder:
    """
    Properties used for a fluent builder pattern.
    Each property returns self for chaining.
    """

    def __init__(self, table):
        self.__table      = table
        self.__conditions = []
        self.__columns    = ["*"]
        self.__limit_val  = None
        self.__order_col  = None
        self.__order_dir  = "ASC"

    def select(self, *columns):
        self.__columns = list(columns)
        return self   # enables chaining!

    def where(self, condition):
        self.__conditions.append(condition)
        return self

    def limit(self, n):
        self.__limit_val = n
        return self

    def order_by(self, column, direction="ASC"):
        self.__order_col = column
        self.__order_dir = direction.upper()
        return self

    @property
    def sql(self):
        """Read-only: builds and returns the SQL string"""
        cols  = ", ".join(self.__columns)
        query = f"SELECT {cols} FROM {self.__table}"
        if self.__conditions:
            query += f" WHERE {' AND '.join(self.__conditions)}"
        if self.__order_col:
            query += f" ORDER BY {self.__order_col} {self.__order_dir}"
        if self.__limit_val:
            query += f" LIMIT {self.__limit_val}"
        return query

    @property
    def count_sql(self):
        """Read-only: count version of the query"""
        query = f"SELECT COUNT(*) FROM {self.__table}"
        if self.__conditions:
            query += f" WHERE {' AND '.join(self.__conditions)}"
        return query

    def __str__(self):
        return self.sql

